	private static TupleExpr codeTypeBranch(String entity, String code, String target, String type, String predicate) {
		return codeTypeBranch(entity, code, target, type, predicate,
				List.of(VF.createLiteral("DX-200"), VF.createLiteral("DX-201"), VF.createLiteral("DX-202")));
	}

	private static TupleExpr codeTypeBranch(String entity, String code, String target, String type, String predicate,
			List<Value> codes) {
		BindingSetAssignment targets = assignment(Set.of(target), row(target, codes.get(0)), row(target, codes.get(1)));
		StatementPattern typePattern = new StatementPattern(Var.of(entity), Var.of("rdfType", RDF.TYPE),
				Var.of("typeValue", VF.createIRI(type)));
		StatementPattern codePattern = new StatementPattern(Var.of(entity),
				Var.of("codePredicate", VF.createIRI(predicate)),
				Var.of(code));
		Join patterns = new Join(typePattern, codePattern);
		patterns.setVariableScopeChange(true);
		Or condition = new Or(new Compare(Var.of(code), Var.of(target), Compare.CompareOp.EQ),
				new Compare(Var.of(code), new ValueConstant(codes.get(2)), Compare.CompareOp.EQ));
		return new Filter(new Join(targets, patterns), condition);
	}

	private static BindingSetAssignment assignment(Set<String> names, BindingSet... rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(names);
		assignment.setBindingSets(List.of(rows));
		return assignment;
	}

	private static MapBindingSet row(Object... namesAndValues) {
		MapBindingSet result = new MapBindingSet();
		for (int i = 0; i < namesAndValues.length; i += 2) {
			result.setBinding((String) namesAndValues[i], (Value) namesAndValues[i + 1]);
		}
		return result;
	}

	private static List<BindingSet> evaluate(TupleExpr expression, List<Statement> statements) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(statements.stream()
						.filter(s -> subject == null || s.getSubject().equals(subject))
						.filter(s -> predicate == null || s.getPredicate().equals(predicate))
						.filter(s -> object == null || s.getObject().equals(object))
						.iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}
